#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    vector<int> numbers(n);
    for (int i = 0; i < n; ++i) {
        cin >> numbers[i];
    }

    vector<int> numbers_mod(n);
    for (int i = 0; i < n; ++i) {
        numbers_mod[i] = numbers[i] % k;
    }

    if (n == 1) {
        cout << numbers_mod[0] << "\n";
        return 0;
    }

    vector<int> partA(numbers_mod.begin(), numbers_mod.begin() + n / 2);
    vector<int> partB(numbers_mod.begin() + n / 2, numbers_mod.end());

    std::set<int> setA, setB, temp_setB;

    for (int val : partA) {
        for (int prev : setA) {
            setB.insert((prev + val) % k);
        }
        setA.insert(val);
        for (int prev : setB) {
            setA.insert(prev);
        }
        setB.clear();
    }

    for (int val : partB) {
        for (int prev : setB) {
            setB.insert((prev + val) % k);
        }
        for (int prev : setA) {
            setB.insert(prev);
        }
    }

    std::vector<int> listA(setA.begin(), setA.end());
    std::vector<int> listB(setB.begin(), setB.end());

    std::sort(listA.begin(), listA.end());
    std::sort(listB.begin(), listB.end());

    int max_res = std::max(listA.back(), listB.back());
    int result = max_res;

    for (int s_elem : listA) {
        int target = k - 1 - s_elem;
        auto it = std::upper_bound(listB.begin(), listB.end(), target);
        if (it != listB.begin()) {
            int r = *(it - 1);
            int rt = listB.back();
            int candidate1 = (r + s_elem) % k;
            int candidate2 = (s_elem + rt) % k;
            result = std::max({result, candidate1, candidate2});
        }
    }

    cout << result << "\n";

    return 0;
}
